cd /tmp && for n in 50 80 100 120 130 135 140 142; do head -$n ~/workspace/pig/incident-2026-09-28/forensics-capture.ps1 > /tmp/b$n.ps1; ~/workspace/pig/pigwsl-put.sh /tmp/b$n.ps1 /mnt/c/Users/nolan/pig-incident-2026-09-28/b$n.ps1 >/dev/null 2>&1; done; printf '%s' 'foreach ($n in 50,80,100,120,130,135,140,142) {
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile("C:/Users/nolan/pig-incident-2026-09-28/b$n.ps1", [ref]$null, [ref]$errors) | Out-Null
$first = if ($errors.Count -gt 0) { "LINE " + $errors[0].Extent.StartLineNumber + ": " + $errors[0].Message } else { "CLEAN" }
Write-Output ("b$n : " + $first)
}' > /tmp/pc4.ps1 && ~/workspace/pig/pigwsl-put.sh /tmp/pc4.ps1 /mnt/c/Users/nolan/pig-incident-2026-09-28/pc4.ps1 >/dev/null && ~/workspace/pig/pigwsl-run.sh 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File C:/Users/nolan/pig-incident-2026-09-28/pc4.ps1' 2>&1 | head -12

~/workspace/pig/pigwsl-run.sh 'cat > /mnt/c/Users/nolan/pig-incident-2026-09-28/evt9.ps1 << "PSEOF"
"=== tasks with repetition < 5min ==="
Get-ScheduledTask -ErrorAction SilentlyContinue | ForEach-Object {
  $t = $_
  foreach ($tr in $t.Triggers) {
    if ($tr.Repetition -and $tr.Repetition.Interval) {
      "{0} :: rep={1} state={2} action={3}" -f $t.TaskName, $tr.Repetition.Interval, $t.State, ($t.Actions | ForEach-Object { $_.Execute + " " + $_.Arguments } | Out-String).Trim()
    }
  }
}
"=== openssh operational 05:00-05:20 ==="
Get-WinEvent -FilterHashtable @{LogName="OpenSSH/Operational"; StartTime=[datetime]"2026-09-28 05:00"; EndTime=[datetime]"2026-09-28 05:20"} -ErrorAction SilentlyContinue | Select-Object TimeCreated,Id,Message | ForEach-Object { "{0:HH:mm:ss} id={1} :: {2}" -f $_.TimeCreated, $_.Id, (( ""+$_.Message) -replace "\s+"," ").Substring(0, [Math]::Min(100, (""+$_.Message).Length)) }
PSEOF
powershell.exe -NoProfile -ExecutionPolicy Bypass -File C:/Users/nolan/pig-incident-2026-09-28/evt9.ps1' 2>&1 | head -40

~/workspace/pig/pigwsl-run.sh 'cat > /mnt/c/Users/nolan/pig-incident-2026-09-28/evt8.ps1 << "PSEOF"
foreach ($t in @("PigiFydStackWatch","PigiGatewayWatch")) {
  "=== TASK $t ==="
  $task = Get-ScheduledTask -TaskName $t -ErrorAction SilentlyContinue
  $task.Actions | ForEach-Object { "ACTION execute={0} args={1}" -f $_.Execute, $_.Arguments }
  $task.Triggers | ForEach-Object { "TRIGGER type={0} enabled={1} boundary={2} rep={3}" -f $_.CimClass.CimClassName, $_.Enabled, $_.StartBoundary, $_.Repetition.Interval }
  $info = Get-ScheduledTaskInfo -TaskName $t -ErrorAction SilentlyContinue
  "LASTRUN={0} RESULT={1} NEXTRUN={2} MISSED={3}" -f $info.LastRunTime, $info.LastTaskResult, $info.NextRunTime, $info.NumberOfMissedRuns
}
PSEOF
powershell.exe -NoProfile -ExecutionPolicy Bypass -File C:/Users/nolan/pig-incident-2026-09-28/evt8.ps1' 2>&1 | head -30
